<?php use App\Core\DB;use App\Models\Content;
$listModule=['homepage'=>'page_sections','navigation'=>'navigation_menus','footer'=>'footer_columns'][$kind];
$addUrl='/admin/'.$listModule.'/new'.($page?'?page_id='.$page['id']:''); ?>
<div class="page-heading"><div><div class="eyebrow"><?=e($kind==='homepage'?$page['title']:'WEBSITE MANAGEMENT')?></div><h1><?=e(['homepage'=>'Make every section count.','navigation'=>'A clear path to your content.','footer'=>'Finish with the right details.'][$kind])?></h1><p>Drag cards to reorder, or use the arrow buttons. Ordering saves immediately.</p></div><div class="actions"><?php if($page):?><a class="button secondary" href="<?=e(cms_url('/admin/preview/pages/'.$page['id']))?>" target="_blank" rel="noopener">Preview ↗</a><a class="button secondary" href="<?=e(cms_url('/admin/pages/'.$page['id']))?>">Page details</a><?php endif?><a class="button" href="<?=e(cms_url($addUrl))?>">＋ <?=$kind==='homepage'?'Add section':($kind==='navigation'?'Add menu':'Add column')?></a></div></div>
<?php if($kind==='footer'):?><div class="builder-callout"><span>◫</span><div><strong>The finishing touches</strong><p>Change the footer logo, description, copyright, and contact details.</p></div><a class="button secondary" href="<?=e(cms_url('/admin/settings/footer'))?>">Footer settings →</a></div><?php endif?>
<div class="builder-list" data-reorder="<?=e($listModule)?>"><?php foreach($records as $item):?><article class="builder-card" draggable="true" data-id="<?=$item['id']?>"><div class="builder-card-head"><span class="drag-handle" aria-label="Drag to reorder">⠿</span><span class="section-icon"><?=match($item['section_type']??''){ 'hero'=>'▣','brands'=>'◎','categories'=>'▦','about'=>'◫','stats'=>'▥',default=>'▤'}?></span><div class="builder-title"><h2><?=e($item['title'])?></h2><p><?=e($item['heading']??$item['location']??$item['content_mode']??'')?></p></div><span class="status <?=e($item['status']??($item['is_active']?'published':'unpublished'))?>"><?=e(ucfirst($item['status']??($item['is_active']?'Visible':'Hidden')))?></span><div class="row-actions"><button type="button" class="icon-button" data-move="up" aria-label="Move up">↑</button><button type="button" class="icon-button" data-move="down" aria-label="Move down">↓</button><a class="button secondary tiny" href="<?=e(cms_url('/admin/'.$listModule.'/'.$item['id']))?>">Edit</a></div></div>
<?php if($kind==='homepage'):?><div class="section-body"><?php if($item['image_id']):?><?=media_img($item['image_id'],$item['title'],'section-thumbnail')?><?php endif?><p><?=e($item['description']?:'Use this section’s editor to manage text, images, buttons and visibility.')?></p><div class="actions"><?php if($item['section_type']==='hero'):?><a class="text-link" href="<?=e(cms_url('/admin/hero_slides?section_id='.$item['id']))?>">Manage slides →</a><?php else:?><a class="text-link" href="<?=e(cms_url('/admin/section_items?section_id='.$item['id']))?>">Manage items & images →</a><?php endif?><a class="text-link" href="<?=e(cms_url('/admin/page_sections/'.$item['id']))?>">Text, buttons & publishing →</a></div></div>
<?php elseif($kind==='navigation'):?><div class="tree-list" data-reorder="navigation_items"><?php $items=DB::all('SELECT * FROM navigation_items WHERE menu_id=? ORDER BY sort_order,id',[$item['id']]);cms_view('admin/menu-tree',['items'=>$items,'parent'=>null,'depth'=>0]);?></div><div class="card-bottom"><a class="text-link" href="<?=e(cms_url('/admin/navigation_items/new?menu_id='.$item['id']))?>">＋ Add menu item</a></div>
<?php else:?><div class="section-body"><?php if($item['content_mode']==='manual'):$links=DB::all('SELECT * FROM footer_menu_items WHERE column_id=? ORDER BY sort_order,id',[$item['id']]);?><div data-reorder="footer_menu_items"><?php foreach($links as $link):?><div class="tree-row" draggable="true" data-id="<?=$link['id']?>"><span class="drag-handle">⠿</span><strong><?=e($link['title'])?></strong><span class="muted"><?=e($link['link_type'])?></span><div class="row-actions"><button class="icon-button" data-move="up" aria-label="Move up">↑</button><button class="icon-button" data-move="down" aria-label="Move down">↓</button><a class="text-link" href="<?=e(cms_url('/admin/footer_menu_items/'.$link['id']))?>">Edit →</a></div></div><?php endforeach?></div><a class="text-link" href="<?=e(cms_url('/admin/footer_menu_items/new?column_id='.$item['id']))?>">＋ Add link</a><?php else:?><p>Automatically shows <?=e($item['content_mode'])?> from your website content.</p><?php endif?></div><?php endif?></article><?php endforeach?></div>
<?php if(!$records):?><div class="panel empty-state"><span>▤</span><h2>Ready to build</h2><p>Add your first <?=$kind==='homepage'?'section':($kind==='navigation'?'menu':'footer column')?>.</p><a class="button" href="<?=e(cms_url($addUrl))?>">＋ Add new</a></div><?php endif?>
